const root=document.documentElement;function themeLabel(){const dark=root.dataset.theme==='dark';$('#theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);$('#theme').setAttribute('aria-pressed',String(dark))}themeLabel();$('#theme').onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('nayo-theme',root.dataset.theme)}catch(e){}themeLabel()};
$('#motion').onclick=()=>{const paused=root.classList.toggle('paused');$('#motion').textContent=paused?'▷':'Ⅱ';$('#motion').setAttribute('aria-label',paused?'Resume animations':'Pause animations');$('#motion').setAttribute('aria-pressed',String(paused))};
$('#menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Close navigation':'Open navigation')};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});
