let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}$('#secret').onclick=()=>{toast('✦ A little pixel magic. Your next idea starts here.');$('#secret').classList.toggle('collected');};
const track=$('.project-track');function step(){return $('.project').offsetWidth+parseFloat(getComputedStyle(track).gap)}function slide(n){track.scrollBy({left:n*step(),behavior:reduced.matches||root.classList.contains('paused')?'instant':'smooth'})}$('#prev').onclick=()=>slide(-1);$('#next').onclick=()=>slide(1);track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();slide(e.key==='ArrowRight'?1:-1)}});track.addEventListener('scroll',()=>{const i=Math.min(4,Math.round(track.scrollLeft/step()));$('#project-count').textContent=`0${i+1} / 05`});let drag=null,suppress=false;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:track.scrollLeft};suppress=false});window.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>5){suppress=true;track.classList.add('dragging');track.scrollLeft=drag.left-dx}});window.addEventListener('pointerup',()=>{drag=null;track.classList.remove('dragging')});track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('click',e=>{if(suppress){e.preventDefault();suppress=false}},true);
const skills=[['UX & Research','Start with people.','Understanding needs, behaviors, and context before shaping the experience.',['User Research','User Experience Design','User Flows','Wireframing','Interactive Prototyping','Usability Testing','Information Architecture']],['UI & Interactive Design','Make every interaction count.','Turning structure into intuitive interfaces, meaningful feedback, and cohesive digital products.',['Interface Design','Digital Product Design','Interaction Design','Design Systems','Human-Computer Interaction']],['Visual & Brand Design','Give ideas a visual voice.','Building thoughtful identities and visual stories across print, screens, and social spaces.',['Graphic Design','Brand Identity','Brand Manuals','Editorial Design','Visual Storytelling','Social Media Graphics']],['Creative Technology','Experiment. Connect. Create.','Exploring tools and AI-assisted workflows to support ideation, research, and visual exploration.',['AI-Assisted Design','AI Creative Tools','Figma','Illustrator','Photoshop','Adobe Creative Cloud','Canva','CapCut']]];
$('.skill-tabs').innerHTML=skills.map((s,i)=>`<button role="tab" id="tab-${i}" aria-controls="skill-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}"><small>0${i+1}</small><span>${s[0]}</span><span>↗</span></button>`).join('');function selectSkill(i){document.querySelectorAll('[role=tab]').forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const s=skills[i];$('#skill-panel').setAttribute('aria-labelledby',`tab-${i}`);$('#skill-panel').innerHTML=`<h3>${s[1]}</h3><p>${s[2]}</p><div class="skill-tags">${s[3].map(x=>`<span>${x}</span>`).join('')}</div>`}document.querySelectorAll('[role=tab]').forEach((b,i)=>{b.onclick=()=>selectSkill(i);b.onkeydown=e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let j=e.key==='Home'?0:e.key==='End'?3:(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:3))%4;selectSkill(j);$(`#tab-${j}`).focus()}}});selectSkill(0);
