if('IntersectionObserver'in window&&!reduced.matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.section-heading,.about-copy,.toolbelt').forEach(e=>{e.classList.add('reveal');observer.observe(e)})}
