const projectCards=[...document.querySelectorAll('.project')];
$('.project-dots').innerHTML=projects.map((p,i)=>`<button aria-label="Show ${p.title}" aria-current="${i===0}" data-project="${i}">0${i+1}</button>`).join('');
function updateGallery(){const max=track.scrollWidth-track.clientWidth;const i=max-track.scrollLeft<3?4:Math.min(4,Math.round(track.scrollLeft/step()));projectCards.forEach((p,j)=>p.classList.toggle('is-active',j===i));document.querySelectorAll('[data-project]').forEach((b,j)=>b.setAttribute('aria-current',String(j===i)));$('#prev').disabled=track.scrollLeft<3;$('#next').disabled=max-track.scrollLeft<3;$('#project-count').textContent=`0${i+1} / 05`}
track.addEventListener('scroll',updateGallery,{passive:true});window.addEventListener('resize',updateGallery);updateGallery();
