// Resolution-independent board. All marks remain local to this page.
const board=$('#drawing-board'),ctx=board.getContext('2d');let marks=[],current=null,mode='pen',redoStack=[];
function point(e){const r=board.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
function paintMark(m){ctx.save();ctx.globalCompositeOperation=m.erase?'destination-out':'source-over';ctx.strokeStyle=m.color;ctx.fillStyle=m.color;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=m.size*board.width;if(m.text){ctx.font=`${m.size*board.width}px Georgia`;ctx.textBaseline='top';const words=m.text.split(' ');let line='',y=m.y*board.height;for(const word of words){const test=line+word+' ';if(ctx.measureText(test).width>board.width*.83&&line){ctx.fillText(line,m.x*board.width,y);line=word+' ';y+=m.size*board.width*1.3}else line=test}ctx.fillText(line,m.x*board.width,y)}else{ctx.beginPath();m.points.forEach((p,i)=>{const x=p.x*board.width,y=p.y*board.height;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(m.points.length===1){const p=m.points[0];ctx.lineTo(p.x*board.width+.01,p.y*board.height+.01)}ctx.stroke()}ctx.restore()}
function renderBoard(){ctx.clearRect(0,0,board.width,board.height);marks.forEach(paintMark);if(current)paintMark(current);$('.canvas-wrap').classList.toggle('has-marks',marks.length>0||!!current);$('#undo').disabled=marks.length===0}
function sizeBoard(){const r=board.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);board.width=Math.round(r.width*d);board.height=Math.round(r.height*d);renderBoard()}
new ResizeObserver(sizeBoard).observe(board);
function setMode(m){mode=m;$('#pen').setAttribute('aria-pressed',String(m==='pen'));$('#eraser').setAttribute('aria-pressed',String(m==='erase'));board.style.cursor=m==='erase'?'cell':'crosshair';$('#board-status').textContent=m==='erase'?'Eraser on. Brush over a mark to remove it.':'Pen on. Draw with your mouse or finger.'}
$('#pen').onclick=()=>setMode('pen');$('#eraser').onclick=()=>setMode('erase');
board.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();board.setPointerCapture(e.pointerId);const r=board.getBoundingClientRect();current={color:$('#ink').value,size:Number($('#brush').value)/r.width,erase:mode==='erase',points:[point(e)]};renderBoard()});
board.addEventListener('pointermove',e=>{if(!current)return;current.points.push(point(e));renderBoard()});function endStroke(){if(!current)return;marks.push(current);redoStack=[];current=null;renderBoard();$('#board-status').textContent='Your mark is on the board. Undo or keep going.'}
board.addEventListener('pointerup',endStroke);board.addEventListener('pointercancel',endStroke);board.addEventListener('lostpointercapture',endStroke);
$('#undo').onclick=()=>{marks.pop();renderBoard();$('#board-status').textContent='Last action undone.'};$('#clear-board').onclick=()=>{if(marks.length){redoStack=marks;marks=[];current=null;renderBoard();$('#board-status').textContent='Board cleared. Click Undo to restore it.';$('#undo').disabled=false}};
$('#undo').onclick=()=>{if(!marks.length&&redoStack.length){marks=redoStack;redoStack=[];$('#board-status').textContent='Cleared board restored.'}else{marks.pop();$('#board-status').textContent='Last action undone.'}renderBoard()};
$('#text-form').onsubmit=e=>{e.preventDefault();const text=$('#board-message').value.trim();if(!text)return;const count=marks.filter(m=>m.text).length;redoStack=[];marks.push({text,color:$('#ink').value,size:.042,x:.08,y:.1+(count%6)*.13});$('#board-message').value='';renderBoard();$('#board-status').textContent='Text added. Draw around it, erase it, or undo.'};
$('#save-board').onclick=()=>{const out=document.createElement('canvas');out.width=board.width;out.height=board.height;const c=out.getContext('2d');c.fillStyle='#fbf5ec';c.fillRect(0,0,out.width,out.height);c.drawImage(board,0,0);const a=document.createElement('a');a.download='my-nayo-artboard.png';a.href=out.toDataURL('image/png');a.click();$('#board-status').textContent='Your drawing is ready to download.'};
